//! dump_physics_scripts — Wave 2.C / Phase 55 (2026-05-28) scaffolding.
//!
//! Opens `client_portal.dat`, finds every `PhysicsScriptTable` (DAT
//! file-type 0x34) and every `PhysicsScript` (0x33) referenced from the
//! tables. Emits a JSON catalog that downstream tooling can consume to
//! build hardcoded `ParticleEmitterInfo` templates for the
//! `_runPlaceholderDispatch` path in `scene3d/play_effect_vfx.js`.
//!
//! ## Why this exists
//!
//! Wave 17 (commit `cf37e6d6`) shipped the live PhysicsScriptTable
//! resolver chain — entities with a non-zero `physicsScriptTableDid`
//! resolve PlayScript IDs into real `PhysicsScript` (0x33) records that
//! drive `ParticleEmitter` (0x32) hooks through the existing Sky-J
//! `ParticleManager`. Entities WITHOUT a table still hit the placeholder
//! path (`_runPlaceholderDispatch` — sphere/cube/torus bursts).
//!
//! For Wave 2.C+ the goal is to ship REAL `ParticleEmitterInfo`-driven
//! visuals for those placeholder cases. This dump enumerates the retail
//! mapping from `PlayScript` enum value → `PhysicsScript` DID(s) so we
//! know which `PhysicsScript` is canonical per `PlayScript` ID — that's
//! the "template" the placeholder path should mimic.
//!
//! ## Usage
//!
//! ```bash
//! cd /home/wbterminal/WorldBuilder-ACME-Edition/external/holtburger
//! export PATH="$HOME/.cargo/bin:$PATH"
//! export HOLTBURGER_PORTAL_DAT=$HOME/ac_base_dats/client_portal.dat
//! cargo run -p holtburger-dat --example dump_physics_scripts
//! ```
//!
//! Writes a JSON catalog to stdout. Pipe to a file for downstream use:
//!
//! ```bash
//! cargo run -p holtburger-dat --example dump_physics_scripts \
//!     > /mnt/wbterminal1/tmp/claude-scratch/wave2c-physics-scripts.json
//! ```
//!
//! ## Output schema
//!
//! ```json
//! {
//!   "_comment": "Generated by `cargo run -p holtburger-dat --example dump_physics_scripts`.",
//!   "_dat_path": "/home/.../client_portal.dat",
//!   "_table_count": N,
//!   "_unique_script_count": M,
//!   "tables": {
//!     "0x34000004": {
//!       "id": 875892740,
//!       "entry_count": 139,
//!       "scripts": {
//!         "4": [
//!           { "mod": 1.0, "scriptDid": "0x33000455" }
//!         ],
//!         "5": [
//!           { "mod": 0.5, "scriptDid": "0x33000123" },
//!           { "mod": 1.0, "scriptDid": "0x33000124" }
//!         ]
//!       }
//!     }
//!   },
//!   "script_hooks": {
//!     "0x33000455": {
//!       "id": 855638613,
//!       "script_data_count": 3,
//!       "particle_hooks": [
//!         {
//!           "start_time": 0.0,
//!           "hook_type": 13,
//!           "emitter_did": "0x32000456",
//!           "part_index": -1,
//!           "offset_xyz": [0.0, 0.0, 0.0],
//!           "offset_quat": [0.0, 0.0, 0.0, 1.0]
//!         }
//!       ]
//!     }
//!   }
//! }
//! ```
//!
//! ## Cross-references
//!
//! - DAT format: `crates/holtburger-dat/src/file_type/physics_script_table.rs`
//! - PhysicsScript (0x33): `crates/holtburger-dat/src/file_type/physics_script.rs`
//! - AnimationHook variants (esp. CreateParticleHook=13, CreateBlockingParticleHook=26):
//!   `crates/holtburger-dat/src/file_type/setup_model.rs`
//! - ACE picker logic: `~/ace-server/Source/ACE.Server/Physics/Scripts/PhysicsScriptTable.cs`
//!   `GetScript(scriptId, mod)`
//! - Retail picker: `acclient.c:336552 PhysicsScriptTableData::GetScript`
//! - Resolver JS port: `scene3d/play_effect_vfx.js:945` `_tryResolveRealVfx`
//!   + `pickScriptEntry` (`acclient.c:336552`)

use binrw::io::Cursor;
use holtburger_dat::DatDatabase;
use holtburger_dat::file_type::physics_script::PhysicsScript;
use holtburger_dat::file_type::physics_script_table::PhysicsScriptTable;
use std::collections::{BTreeMap, BTreeSet};
use std::path::PathBuf;
use std::process::ExitCode;

fn resolve_dat_path() -> Option<PathBuf> {
    if let Some(path) = holtburger_dat::utils::get_portal_dat_path() {
        return Some(path);
    }
    if let Ok(home) = std::env::var("HOME") {
        let p = PathBuf::from(home).join("ac_base_dats/client_portal.dat");
        if p.exists() {
            return Some(p);
        }
    }
    None
}

/// Extract the (hook_type, emitter_did, part_index, offset, quaternion)
/// for every CreateParticle (13) and CreateBlockingParticle (26) entry
/// inside a `PhysicsScript`. Other hook variants (Sound=1, NoOp, etc.)
/// are skipped — the dispatch path on the JS side only spawns particles
/// from these two hook types (see `play_effect_vfx.js:1038`).
///
/// `AnimationHook::as_create_particle()` (setup_model.rs:164) returns
/// `Some(CreateParticleHookPayload)` for hook_type 13 or 26; we project
/// from there into JSON.
fn extract_particle_hooks(ps: &PhysicsScript) -> Vec<serde_json::Value> {
    let mut out = Vec::new();
    for entry in &ps.script_data {
        if let Some(payload) = entry.hook.as_create_particle() {
            out.push(serde_json::json!({
                "start_time": entry.start_time,
                "hook_type": entry.hook.hook_type,
                "emitter_did": format!("0x{:08X}", payload.emitter_info_id),
                // part_index 0xFFFFFFFF == -1 == "root" (whole-object attachment).
                "part_index": payload.part_index as i64,
                "emitter_id": payload.emitter_id,
                "offset_xyz": [
                    payload.offset.origin.x,
                    payload.offset.origin.y,
                    payload.offset.origin.z,
                ],
                // Frame.orientation is a Quaternion (w,x,y,z) in retail
                // DAT order. Emit explicitly as `wxyz` so JS consumers know
                // to flip to xyzw when constructing THREE.Quaternion.
                "offset_quat_wxyz": [
                    payload.offset.orientation.w,
                    payload.offset.orientation.x,
                    payload.offset.orientation.y,
                    payload.offset.orientation.z,
                ],
            }));
        }
    }
    out
}

fn main() -> ExitCode {
    let Some(dat_path) = resolve_dat_path() else {
        eprintln!(
            "client_portal.dat not found: set HOLTBURGER_PORTAL_DAT or place a copy at \
             ~/ac_base_dats/client_portal.dat"
        );
        return ExitCode::from(2);
    };

    let dat = match DatDatabase::new(&dat_path) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("failed to open {}: {e}", dat_path.display());
            return ExitCode::from(2);
        }
    };

    // ----- Phase 1: enumerate every 0x34xxxxxx (PhysicsScriptTable) ID
    // and parse it. Collect the union of referenced 0x33xxxxxx
    // (PhysicsScript) IDs for the second pass.
    // -----------------------------------------------------------------
    let mut table_ids: Vec<u32> = dat
        .files
        .keys()
        .copied()
        .filter(|id| (*id & 0xFF00_0000) == 0x3400_0000)
        .collect();
    table_ids.sort_unstable();

    let mut tables_json = serde_json::Map::new();
    let mut referenced_scripts: BTreeSet<u32> = BTreeSet::new();
    let mut play_script_keys_seen: BTreeSet<u32> = BTreeSet::new();

    for tid in &table_ids {
        let bytes = match dat.get_file(*tid) {
            Ok(b) => b,
            Err(e) => {
                eprintln!("WARN: failed to read PhysicsScriptTable 0x{tid:08X}: {e}");
                continue;
            }
        };
        let mut cursor = Cursor::new(&bytes);
        let table = match PhysicsScriptTable::read(&mut cursor) {
            Ok(t) => t,
            Err(e) => {
                eprintln!("WARN: failed to parse PhysicsScriptTable 0x{tid:08X}: {e}");
                continue;
            }
        };

        // BTreeMap so PlayScript keys come out sorted in JSON.
        let mut scripts_map: BTreeMap<String, Vec<serde_json::Value>> = BTreeMap::new();
        for (play_script_key, data) in &table.script_table {
            play_script_keys_seen.insert(*play_script_key);
            let mut entries_json = Vec::new();
            for entry in &data.scripts {
                referenced_scripts.insert(entry.script_id);
                entries_json.push(serde_json::json!({
                    "mod": entry.mod_value,
                    "scriptDid": format!("0x{:08X}", entry.script_id),
                }));
            }
            scripts_map.insert(format!("{}", play_script_key), entries_json);
        }

        tables_json.insert(
            format!("0x{:08X}", *tid),
            serde_json::json!({
                "id": table.id,
                "entry_count": table.script_table.len(),
                "scripts": scripts_map,
            }),
        );
    }

    // ----- Phase 2: parse every referenced PhysicsScript (0x33xxxxxx)
    // and extract the CreateParticle / CreateBlockingParticle hooks.
    // -----------------------------------------------------------------
    let mut script_hooks_json = serde_json::Map::new();
    let mut hook_parse_failures: Vec<(u32, String)> = Vec::new();
    let mut scripts_with_no_particle_hook: Vec<u32> = Vec::new();
    let mut total_particle_hook_count: usize = 0;
    for sid in &referenced_scripts {
        let bytes = match dat.get_file(*sid) {
            Ok(b) => b,
            Err(e) => {
                hook_parse_failures.push((*sid, format!("fetch: {e}")));
                continue;
            }
        };
        let mut cursor = Cursor::new(&bytes);
        let ps = match PhysicsScript::read(&mut cursor) {
            Ok(s) => s,
            Err(e) => {
                hook_parse_failures.push((*sid, format!("parse: {e}")));
                continue;
            }
        };
        let hooks = extract_particle_hooks(&ps);
        total_particle_hook_count += hooks.len();
        if hooks.is_empty() {
            scripts_with_no_particle_hook.push(*sid);
        }
        script_hooks_json.insert(
            format!("0x{:08X}", *sid),
            serde_json::json!({
                "id": ps.id,
                "script_data_count": ps.script_data.len(),
                "particle_hooks": hooks,
            }),
        );
    }

    // ----- Phase 3: emit. JSON to stdout; diag to stderr.
    let out = serde_json::json!({
        "_comment": "Generated by `cargo run -p holtburger-dat --example dump_physics_scripts`. \
                     See file header for schema.",
        "_dat_path": dat_path.display().to_string(),
        "_table_count": table_ids.len(),
        "_unique_play_script_keys": play_script_keys_seen.len(),
        "_unique_script_count": referenced_scripts.len(),
        "_total_particle_hooks": total_particle_hook_count,
        "_scripts_with_no_particle_hook": scripts_with_no_particle_hook.len(),
        "_parse_failures": hook_parse_failures.len(),
        "tables": tables_json,
        "script_hooks": script_hooks_json,
    });

    println!("{}", serde_json::to_string_pretty(&out).unwrap_or_default());

    eprintln!();
    eprintln!("## Summary");
    eprintln!(
        "  {} PhysicsScriptTable (0x34) records",
        table_ids.len()
    );
    eprintln!(
        "  {} unique PlayScript keys mentioned across all tables",
        play_script_keys_seen.len()
    );
    eprintln!(
        "  {} unique PhysicsScript (0x33) records referenced",
        referenced_scripts.len()
    );
    eprintln!(
        "  {} total CreateParticle / CreateBlockingParticle hooks",
        total_particle_hook_count
    );
    eprintln!(
        "  {} PhysicsScripts referenced but with no particle hooks (sound-only?)",
        scripts_with_no_particle_hook.len()
    );
    if !hook_parse_failures.is_empty() {
        eprintln!(
            "  WARN {} PhysicsScripts failed to fetch/parse",
            hook_parse_failures.len()
        );
        for (sid, msg) in &hook_parse_failures {
            eprintln!("    0x{:08X}: {}", sid, msg);
        }
    }

    ExitCode::SUCCESS
}
